contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 probe) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(probe == 0);
        require(c.getBalance(address(this)) == 0);
        uint256 cBalBefore = address(c).balance;
        uint256 callerBalBefore = address(this).balance;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        assert(
            c.getBalance(address(this)) == 0
            && address(c).balance == cBalBefore
            && address(this).balance == callerBalBefore
        );
    }

    receive() external payable {}
}

